2.query:
// Stacked bar: technology x status
// STEP 1 - Processes reporting any tracked technology, then the host each one runs on
smartscapeNodes PROCESS
| fieldsAdd tech_types = arrayConcat(coalesce(process.software_technologies.os, array()), coalesce(process.software_technologies.java, array()))[][type]
| filter iAny(tech_types[] == "JAVA") or iAny(tech_types[] == "DOTNET") or iAny(tech_types[] == "NODE_JS") or iAny(tech_types[] == "PYTHON") or iAny(tech_types[] == "PHP") or iAny(tech_types[] == "GO") or iAny(tech_types[] == "NGINX") or iAny(tech_types[] == "APACHE_HTTP_SERVER") or iAny(tech_types[] == "IIS_APP_POOL") or iAny(tech_types[] == "APACHE_TOMCAT") or iAny(tech_types[] == "SPRING") or iAny(tech_types[] == "APACHE_LOG4J") or iAny(tech_types[] == "APACHE_KAFKA") or iAny(tech_types[] == "REDIS") or iAny(tech_types[] == "IBM_WEBSPHERE_APPLICATION_SERVER") or iAny(tech_types[] == "IBM_WEBSPHERE_LIBERTY") or iAny(tech_types[] == "OPEN_LIBERTY") or iAny(tech_types[] == "ORACLE_WEBLOGIC") or iAny(tech_types[] == "WILDFLY") or iAny(tech_types[] == "JBOSS_EAP")
| fieldsAdd proc_id = id, proc_name = name
| lookup [
    smartscapeNodes PROCESS
    | traverse {runs_on}, {HOST}, fieldsKeep:{name}
    | fieldsAdd lk_proc = dt.traverse.history[0][id]
    | fields lk_proc, lk_host_name = name, lk_host_id = id
    | dedup lk_proc
  ], sourceField:proc_id, lookupField:lk_proc, fields:{lk_host_name, lk_host_id}
| lookup [
    smartscapeNodes PROCESS
    | traverse {runs_on}, {CONTAINER}, fieldsKeep:{name}
    | fieldsAdd lk_proc2 = dt.traverse.history[0][id]
    | fields lk_proc2, lk_container_name = name
    | dedup lk_proc2
  ], sourceField:proc_id, lookupField:lk_proc2, fields:{lk_container_name}
| lookup [
    smartscapeNodes PROCESS
    | traverse {runs_on}, {CONTAINER}
    | traverse {runs_on}, {HOST}, fieldsKeep:{name}
    | fieldsAdd lk_proc3 = dt.traverse.history[0][id]
    | fields lk_proc3, lk_chost_name = name, lk_chost_id = id
    | dedup lk_proc3
  ], sourceField:proc_id, lookupField:lk_proc3, fields:{lk_chost_name, lk_chost_id}
| fieldsAdd name = coalesce(lk_host_name, lk_chost_name, if(isNotNull(lk_container_name), concat("(container) ", lk_container_name)), "(no host link)"), id = coalesce(lk_host_id, lk_chost_id, "none")

// STEP 2 - One row per technology entry on the process
| fieldsAdd technology = arrayConcat(coalesce(process.software_technologies.os, array()), coalesce(process.software_technologies.java, array()))
| expand technology
| fieldsAdd tech_type = technology[type]
| filter in(tech_type, array("JAVA","DOTNET","NODE_JS","PYTHON","PHP","GO","NGINX","APACHE_HTTP_SERVER","IIS_APP_POOL","APACHE_TOMCAT","SPRING","APACHE_LOG4J","APACHE_KAFKA","REDIS","IBM_WEBSPHERE_APPLICATION_SERVER","IBM_WEBSPHERE_LIBERTY","OPEN_LIBERTY","ORACLE_WEBLOGIC","WILDFLY","JBOSS_EAP"))
| fieldsAdd tech_version = coalesce(technology[version], ""), tech_edition = technology[edition]
| fieldsAdd tech_version = arrayLast(splitString(tech_version, "/"))
| fieldsAdd has_version = tech_version != "" and tech_version != "null"

// STEP 3 - One row per process + technology (prefer the entry that has a version)
| dedup {proc_id, tech_type}, sort: {has_version desc}
| fieldsAdd process.name = proc_name, host.name = name, host_id = id

// STEP 4 - Security status from Dynatrace Application Security (open vulnerabilities per host + technology). No support-date assumptions.
//   CRITICAL / HIGH / MEDIUM / LOW = highest risk level among open vulnerabilities reported for that host and technology
//   UNRATED = open vulnerabilities with no risk level   NO FINDINGS = none reported (may also mean the host is not covered by Application Security)
| fieldsAdd sec_key = concat(host.name, "|", tech_type)
| lookup [
    fetch security.events
    | filter event.provider == "Dynatrace" and event.type == "VULNERABILITY_STATE_REPORT_EVENT" and event.level == "ENTITY"
    | filter vulnerability.resolution.status == "OPEN"
    | dedup {vulnerability.display_id, affected_entity.id}, sort: {timestamp desc}
    | fieldsAdd lvl = coalesce(vulnerability.parent.davis_assessment.level, vulnerability.davis_assessment.level, vulnerability.risk.level, "")
    | fieldsAdd rank = if(lvl == "CRITICAL", 4, else: if(lvl == "HIGH", 3, else: if(lvl == "MEDIUM", 2, else: if(lvl == "LOW", 1, else: 0))))
    | fieldsAdd sec_host = coalesce(related_entities.hosts.names, array("(no host reported)"))
    | expand sec_host
    | fieldsAdd lk_sec_key = concat(sec_host, "|", vulnerability.technology)
    | summarize sec_rank = max(rank), sec_vulns = countDistinct(vulnerability.display_id), by:{lk_sec_key}
  ], sourceField:sec_key, lookupField:lk_sec_key, fields:{sec_rank, sec_vulns}
| fieldsAdd security_status = if(isNull(sec_rank), "NO FINDINGS", else: if(sec_rank == 4, "CRITICAL", else: if(sec_rank == 3, "HIGH", else: if(sec_rank == 2, "MEDIUM", else: if(sec_rank == 1, "LOW", else: "UNRATED")))))
| fieldsAdd open_vulnerabilities = coalesce(sec_vulns, 0)
| fieldsAdd priority = if(isNull(sec_rank), 6, else: 5 - sec_rank)


// STEP 5 - Dashboard variable filters
| filter in(tech_type, if(arraySize(array($technology)) == 0, array(""), else: array($technology)))
| filter in(security_status, if(arraySize(array($security_status)) == 0, array(""), else: array($security_status)))
| filter in("*ALL*", array($host_name)) or host.name == "(no host link)" or startsWith(host.name, "(container) ") or in(host.name, if(arraySize(array($host_name)) == 0, array(""), else: array($host_name)))

| summarize processes = count(), by:{tech_type, security_status}
| sort tech_type asc

