//   UNRATED = open vulnerabilities with no risk level   NO FINDINGS = none reported (may also mean the host is not covered by Application Security)
| fieldsAdd proc_key = concat(host.name, "|", tech_type, "|", proc_name), host_key = concat(host.name, "|", tech_type)
| fieldsAdd sec_key = array(proc_key, host_key)
| expand sec_key
| fieldsAdd key_priority = if(sec_key == proc_key, 1, else: 2)
| lookup [
    fetch security.events
    | filter event.provider == "Dynatrace" and event.type == "VULNERABILITY_STATE_REPORT_EVENT" and event.level == "ENTITY"
    | filter vulnerability.resolution.status == "OPEN"
