| dedup {proc_id, tech_type}, sort: {has_match desc, key_priority asc}
| fieldsAdd match_level = if(has_match == false, "none", else: if(key_priority == 1, "process", else: "host"))
| fieldsAdd security_status = if(isNull(sec_rank), "NO FINDINGS", else: if(sec_rank == 4, "CRITICAL", else: if(sec_rank == 3, "HIGH", else: if(sec_rank == 2, "MEDIUM", else: if(sec_rank == 1, "LOW", else: "UNRATED")))))
